<template><AppLayout page-title="Notifications"><div class="card"><div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div v-else-if="!items.length" class="empty-state">Aucune notification.</div><div v-for="n in items" :key="n.id" class="notification" :class="{unread:!n.is_read}" @click="markRead(n)"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{new Date(n.created_at).toLocaleString('fr-FR')}}</small></div></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore(),items=ref<any[]>([]),loading=ref(true);onMounted(async()=>{if(!auth.user)return;const {data}=await supabase.from('notifications').select('*').eq('recipient_id',auth.user.id).order('created_at',{ascending:false}).limit(100);items.value=data||[];loading.value=false});async function markRead(n:any){if(n.is_read)return;n.is_read=true;await supabase.from('notifications').update({is_read:true,read_at:new Date().toISOString()}).eq('id',n.id)}</script>